const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs'),vm=require('node:vm');
const source=fs.readFileSync('internal/web/static/app.js','utf8').split('// Status requests only read the server cache; the page request schedules DNS.\n')[1];
function setup(nodes){const events={},body={},win={},timers=[],req=[];const document={querySelectorAll:s=>nodes.filter(n=>s==='[data-asn]'?n.dataset.asn:n.dataset.ptr),addEventListener:(n,f)=>events[n]=f,body:{addEventListener:(n,f)=>body[n]=f}};vm.runInNewContext(source,{document,window:{addEventListener:(n,f)=>win[n]=f},fetch:url=>new Promise(resolve=>req.push({url,resolve})),setTimeout:f=>timers.push(f),encodeURIComponent,Promise});return {events,body,win,timers,req,set(n){nodes=n}}}
const settle=async()=>{for(let i=0;i<10;i++)await Promise.resolve()};
test('ASN and PTR share one timer and update duplicates',async()=>{const a={dataset:{asn:'13335'},title:'',isConnected:true},p={dataset:{ptr:'2001:db8::1'},title:'',isConnected:true},q={dataset:{ptr:'2001:db8::1'},title:'',isConnected:true};const h=setup([a,p,q]);h.events.DOMContentLoaded();assert.equal(h.timers.length,1);h.timers.shift()();assert.equal(h.req.length,2);h.req[0].resolve({ok:true,json:async()=>({'13335':'ASN name'})});h.req[1].resolve({ok:true,json:async()=>({'2001:db8::1':'Router.Example'})});await settle();assert.equal(a.title,'ASN name');assert.equal(p.title,'Router.Example');assert.equal(q.title,p.title);assert.equal(h.timers.length,0)});
test('PTR-only navigation discards stale responses and restores history',async()=>{const old={dataset:{ptr:'192.0.2.1'},title:'',isConnected:true},fresh={dataset:{ptr:'2001:db8::1'},title:'',isConnected:true};const h=setup([old]);h.events.DOMContentLoaded();h.timers.shift()();old.isConnected=false;h.set([fresh]);h.body['htmx:afterSwap']();h.timers.shift()();h.req[0].resolve({ok:true,json:async()=>({'192.0.2.1':'old'})});h.req[1].resolve({ok:true,json:async()=>({'2001:db8::1':'new'})});await settle();assert.equal(old.title,'');assert.equal(fresh.title,'new');h.win.pagehide();h.win.pageshow({persisted:true});assert.equal(h.timers.length,0)});
test('PTR malformed and failed cache responses do not update addresses',async()=>{for(const response of [{ok:false},{ok:true,json:async()=>null},{ok:true,json:async()=>({'192.0.2.1':{}})},{ok:true,json:async()=>{throw Error('bad JSON')}}]){const p={dataset:{ptr:'192.0.2.1'},title:'',isConnected:true};const h=setup([p]);h.events.DOMContentLoaded();h.timers.shift()();h.req[0].resolve(response);await settle();assert.equal(p.title,'');h.win.pagehide()}});
